slides.code:
function greet(name) {   // name — PARAMETR
  return "Salom, " + name;
}
greet("Anya");           // "Anya" — ARGUMENT

function introduce(name, age) {
  return `Mening ismim ${name}, men ${age} yoshdaman`;
}
console.log(introduce("Aziz", 16));
// Mening ismim Aziz, men 16 yoshdaman

function greetNoReturn(name) {
  "Salom, " + name; // return yo'q
}
console.log(greetNoReturn("Anya")); // undefined

// 1. oddiy
function greet(name) {
  return "Salom, " + name;
}

// 2. strelkali
const greet = (name) => {
  return "Salom, " + name;
};

// 3. strelkali, qisqa
const greet = name => "Salom, " + name;

slides.text:
Qanday qisqartiriladi:
parametr bitta — uning atrofidagi qavslarni olib tashlash mumkin;
ichida faqat return — `{ }` va `return` so'zini olib tashlaymiz;
parametrlar ikki va undan ko'p — qavslar qoladi: `(a, b) => a + b`.

slides.code:
function welcome(name) {
  return `Salom, ${name}! Darsga xush kelibsan.`;
}
console.log(welcome("Aziz"));
console.log(welcome("Ali"));

const names = ["Aziz", "Ali", "Malika"];
for (const name of names) {
  console.log(welcome(name));
}

function sum(a, b) {
  return a + b;
}
console.log(sum(2, 3));  // 5
console.log(sum(-5, 5)); // 0

// strelkali funksiya bilan:
const sum = (a, b) => a + b;

